13	// fakeEchoAPI is an echoAPI whose echo either answers at once (answer set) or
14	// blocks until release is closed, like IcmpSendEcho does.
15	type fakeEchoAPI struct {
16		mu        sync.Mutex
17		creates   int
18		closes    int
19		inflight  int
20		maxFlight int
21		busy      map[uintptr]bool
22		dsts      []netip.Addr
23		ttls      []int
24		timeouts  []time.Duration
25		violation string
26	
27		createErr error
28		// answer, when not nil, is returned at once; otherwise echo blocks.
29		answer  func(ttl int) (reply, error)
30		started chan struct{} // one value per echo call, buffered
31		release chan struct{} // closing it frees every blocked echo
32	}
33	
34	func newFakeEchoAPI() *fakeEchoAPI {
35		return &fakeEchoAPI{
36			busy:    map[uintptr]bool{},
37			started: make(chan struct{}, 64),
38			release: make(chan struct{}),
39		}
40	}
41	
42	func (f *fakeEchoAPI) create() (uintptr, error) {
43		f.mu.Lock()
44		defer f.mu.Unlock()
45		if f.createErr != nil {
46			return 0, f.createErr
47		}
48		f.creates++
49		return uintptr(f.creates), nil
50	}
51	
52	func (f *fakeEchoAPI) echo(h uintptr, dst netip.Addr, ttl int, timeout time.Duration) (reply, error) {
53		f.mu.Lock()
54		f.busy[h] = true
55		f.inflight++
56		if f.inflight > f.maxFlight {
57			f.maxFlight = f.inflight
58		}
59		f.dsts = append(f.dsts, dst)
60		f.ttls = append(f.ttls, ttl)
61		f.timeouts = append(f.timeouts, timeout)
62		answer := f.answer
63		f.mu.Unlock()
64		f.started <- struct{}{}
65	
66		defer func() {
67			f.mu.Lock()
68			f.busy[h] = false
69			f.inflight--
70			f.mu.Unlock()
71		}()
72		if answer != nil {
73			return answer(ttl)
74		}
75		<-f.release
76		return reply{}, errSilent
77	}
78	
79	func (f *fakeEchoAPI) closeHandle(h uintptr) error {
80		f.mu.Lock()
81		defer f.mu.Unlock()
82		if f.busy[h] {
83			f.violation = "closeHandle called while echo was still running"
84		}
85		f.closes++
86		return nil
87	}
88	
89	func (f *fakeEchoAPI) counts() (creates, closes, inflight int) {
90		f.mu.Lock()
91		defer f.mu.Unlock()
92		return f.creates, f.closes, f.inflight
93	}
94	
95	func (f *fakeEchoAPI) waitStarted(t *testing.T, n int) {
96		t.Helper()
97		for i := 0; i < n; i++ {
98			select {
99			case <-f.started:
100			case <-time.After(2 * time.Second):
101				t.Fatalf("echo call %d of %d never started", i+1, n)
102			}
103		}
104	}
105	
106	// waitFor polls cond up to 2 s; it only bounds a wait, it never replaces a sync.
107	func waitFor(t *testing.T, what string, cond func() bool) {
108		t.Helper()
109		deadline := time.Now().Add(2 * time.Second)
110		for !cond() {
111			if time.Now().After(deadline) {
112				t.Fatalf("timed out waiting for %s", what)
113			}
114			time.Sleep(time.Millisecond)
115		}
116	}
117	
118	func noPreflight(context.Context, netip.Addr) error { return nil }
119	
120	func newEchoProber(api echoAPI) *echoProber {
121		return &echoProber{api: api, preflight: noPreflight}
122	}
123	
124	func mustOpen(t *testing.T, p *echoProber, ttl int) probeConn {
125		t.Helper()
126		c, err := p.open(context.Background(), engineTarget, ttl)
127		if err != nil {
128			t.Fatalf("open: %v", err)
129		}
130		return c
131	}
