137	func TestEchoProberOpenPassesTTLAndDestination(t *testing.T) {
138		api := newFakeEchoAPI()
139		api.answer = func(int) (reply, error) { return echoReply(ipSuccess, engineTarget) }
140		c := mustOpen(t, newEchoProber(api), 7)
141		sentAt, err := c.send()
142		if err != nil || sentAt.IsZero() {
143			t.Fatalf("send = %v, %v", sentAt, err)
144		}
145		if _, err := c.await(context.Background(), sentAt.Add(time.Second)); err != nil {
146			t.Fatalf("await: %v", err)
147		}
148		api.mu.Lock()
149		defer api.mu.Unlock()
150		if len(api.ttls) != 1 || api.ttls[0] != 7 {
151			t.Errorf("ttls = %v, want [7]", api.ttls)
152		}
153		if len(api.dsts) != 1 || api.dsts[0] != engineTarget {
154			t.Errorf("dsts = %v, want [%v]", api.dsts, engineTarget)
155		}
