157	
158	func TestEchoProberPassesTheRemainingTimeAsTimeout(t *testing.T) {
159		tests := []struct {
160			name     string
161			until    time.Duration // relative to the send
162			min, max time.Duration
163		}{
164			{"remaining time", 500 * time.Millisecond, 400 * time.Millisecond, 500 * time.Millisecond},
165			{"deadline already past is one millisecond", -time.Second, time.Millisecond, time.Millisecond},
166		}
167		for _, tt := range tests {
168			t.Run(tt.name, func(t *testing.T) {
169				api := newFakeEchoAPI()
170				api.answer = func(int) (reply, error) { return reply{}, errSilent }
171				c := mustOpen(t, newEchoProber(api), 3)
172				sentAt, _ := c.send()
173				if _, err := c.await(context.Background(), sentAt.Add(tt.until)); !errors.Is(err, errSilent) {
174					t.Fatalf("await err = %v, want errSilent", err)
175				}
176				api.mu.Lock()
177				got := append([]time.Duration(nil), api.timeouts...)
178				api.mu.Unlock()
179				if len(got) != 1 || got[0] < tt.min || got[0] > tt.max {
180					t.Errorf("timeout = %v, want in [%v, %v]", got, tt.min, tt.max)
181				}
182			})
183		}
184	}
185	
186	func TestEchoConnAwaitReturnsTheReply(t *testing.T) {
187		api := newFakeEchoAPI()
188		api.answer = func(int) (reply, error) { return echoReply(ipTTLExpiredTransit, netip.MustParseAddr("10.0.0.1")) }
189		c := mustOpen(t, newEchoProber(api), 1)
190		sentAt, _ := c.send()
191		rep, err := c.await(context.Background(), sentAt.Add(time.Second))
192		if err != nil {
193			t.Fatalf("await: %v", err)
194		}
195		if rep.Addr != netip.MustParseAddr("10.0.0.1") || rep.Origin != originEcho || rep.Status != ipTTLExpiredTransit {
196			t.Errorf("reply = %+v", rep)
197		}
198		if err := c.close(); err != nil {
199			t.Errorf("close: %v", err)
200		}
201		if _, closes, _ := api.counts(); closes != 1 {
202			t.Errorf("closeHandle calls = %d, want 1", closes)
203		}
204	}
205	
206	func TestEchoConnAwaitPropagatesAFailure(t *testing.T) {
207		api := newFakeEchoAPI()
208		api.answer = func(int) (reply, error) { return reply{}, &EchoStatusError{Status: ipGeneralFailure} }
209		c := mustOpen(t, newEchoProber(api), 1)
210		sentAt, _ := c.send()
211		_, err := c.await(context.Background(), sentAt.Add(time.Second))
212		var se *EchoStatusError
213		if !errors.As(err, &se) || se.Status != ipGeneralFailure {
214			t.Fatalf("await err = %v, want *EchoStatusError %d", err, ipGeneralFailure)
215		}
216	}
217	
218	func TestEchoConnCancelDuringBlockedEcho(t *testing.T) {
219		api := newFakeEchoAPI()
220		c := mustOpen(t, newEchoProber(api), 5)
221		ctx, cancel := context.WithCancel(context.Background())
222		defer cancel()
223		sentAt, _ := c.send()
224	
225		done := make(chan error, 1)
226		go func() {
227			_, err := c.await(ctx, sentAt.Add(10*time.Second))
228			done <- err
229		}()
230		api.waitStarted(t, 1)
231	
232		cancelledAt := time.Now()
233		cancel()
234		select {
235		case err := <-done:
236			if !errors.Is(err, context.Canceled) {
237				t.Fatalf("await err = %v, want context.Canceled", err)
238			}
239			if d := time.Since(cancelledAt); d > 50*time.Millisecond {
240				t.Errorf("await took %v to notice the cancellation, want < 50ms", d)
241			}
242		case <-time.After(2 * time.Second):
243			t.Fatal("await did not return after cancel")
244		}
245	
246		// The echo is still blocked: the handle must stay open, close or not.
247		_ = c.close()
248		_ = c.close()
249		if _, closes, inflight := api.counts(); closes != 0 || inflight != 1 {
250			t.Fatalf("before release: closes = %d, inflight = %d, want 0 and 1", closes, inflight)
251		}
252	
253		close(api.release)
254		waitFor(t, "the deferred closeHandle", func() bool { _, c, _ := api.counts(); return c == 1 })
255		waitFor(t, "echo to return", func() bool { _, _, f := api.counts(); return f == 0 })
256		_ = c.close()
257		if _, closes, _ := api.counts(); closes != 1 {
258			t.Errorf("closeHandle calls = %d, want exactly 1", closes)
259		}
260		if api.violation != "" {
261			t.Error(api.violation)
262		}
263	}
