410	func TestEchoProberRunCancelledLeavesNoGoroutine(t *testing.T) {
411		api := newFakeEchoAPI()
412		ctx, cancel := context.WithCancel(context.Background())
413		defer cancel()
414		go func() {
415			for i := 0; i < 30; i++ { // every TTL is blocked inside echo
416				select {
417				case <-api.started:
418				case <-time.After(2 * time.Second):
419					return // the main goroutine's checks fail on the counts
420				}
421			}
422			cancel()
423		}()
424	
425		res := mustRun(t, ctx, Options{MaxHops: 30, ProbeTimeout: 10 * time.Second}, newEchoProber(api))
426		if res.Outcome != OutcomeCancelled {
427			t.Fatalf("Outcome = %v, want cancelled", res.Outcome)
428		}
429		// run has returned while the 30 echoes are still blocked: no handle may be
430		// closed under them, and none may be leaked afterwards.
431		if creates, closes, inflight := api.counts(); creates != 30 || closes != 0 || inflight != 30 {
432			t.Fatalf("at return: creates = %d, closes = %d, inflight = %d, want 30, 0, 30", creates, closes, inflight)
433		}
434		close(api.release)
435		waitFor(t, "30 closes and no echo left", func() bool {
436			_, cl, f := api.counts()
437			return cl == 30 && f == 0
438		})
439		if api.violation != "" {
440			t.Error(api.violation)
441		}
442	}
