8	// IsNoRoute reports whether err means "this machine has no route to the
9	// target": ErrNoRoute, or a raw network/host unreachable errno anywhere in the
10	// chain. The error text alone never counts (it is localized). It is the single
11	// place that classifies a no-route failure.
12	func IsNoRoute(err error) bool {
13		if errors.Is(err, ErrNoRoute) ||
14			errors.Is(err, syscall.ENETUNREACH) ||
15			errors.Is(err, syscall.EHOSTUNREACH) {
16			return true
17		}
18		for _, errno := range platformNoRouteErrnos {
19			if errors.Is(err, errno) {
20				return true
21			}
22		}
23		return false
24	}
